package com.keyforge.nativeiiq.resource;
import com.keyforge.nativeiiq.model.NativeWorkflowExtractionResult; import com.keyforge.nativeiiq.service.NativeWorkflowExtractionService; import com.keyforge.nativeiiq.wire.NativeWorkflowWire; import sailpoint.api.SailPointContext; import sailpoint.authorization.UnauthorizedAccessException; import sailpoint.rest.plugin.*; import javax.ws.rs.*; import javax.ws.rs.core.*; import java.util.Map; import java.util.logging.*;
@Path("keyForgeNativeIIQ") public class NativeWorkflowResource extends BasePluginResource { private static final Logger LOG=Logger.getLogger(NativeWorkflowResource.class.getName()); public String getPluginName(){return "KeyForgeNativeIIQ";} @GET @Path("workflows") @SystemAdmin @Produces(MediaType.APPLICATION_JSON) public Response get(@QueryParam("start") @DefaultValue("0") int start,@QueryParam("limit") @DefaultValue("100") int limit,@QueryParam("runId") String runId){int s=Math.max(0,start),l=limit<=0?100:Math.min(limit,1000);String stage="context";try{SailPointContext c=getContext();stage="extract";NativeWorkflowExtractionResult r=new NativeWorkflowExtractionService().extract(c,s,l,runId);Map<String,Object>body=NativeWorkflowWire.envelope(r,s,l);return Response.ok(body).build();}catch(UnauthorizedAccessException e){LOG.log(Level.WARNING,"Native workflow denied at "+stage,e);return Response.status(403).type(MediaType.APPLICATION_JSON).entity(NativeWorkflowWire.error(403,e)).build();}catch(Throwable t){LOG.log(Level.SEVERE,"Native workflow failed at "+stage,t);return Response.status(500).type(MediaType.APPLICATION_JSON).entity(NativeWorkflowWire.error(500,t)).build();}} }
